import{_ as i,o as r,c as a,a0 as t}from"./chunks/framework.CBux2OW7.js";const m=JSON.parse('{"title":"Services","description":"","frontmatter":{},"headers":[],"relativePath":"backend/services.md","filePath":"backend/services.md"}'),s={name:"backend/services.md"};function o(n,e,l,c,d,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h1><p>The <code>app/Services/</code> directory encapsulates all the core business logic of TechyNews. By isolating complex operations into services, we keep our controllers clean and make the code easier to test and maintain.</p><h2 id="key-services" tabindex="-1">Key Services <a class="header-anchor" href="#key-services" aria-label="Permalink to &quot;Key Services&quot;">​</a></h2><h3 id="newsservice" tabindex="-1"><code>NewsService</code> <a class="header-anchor" href="#newsservice" aria-label="Permalink to &quot;`NewsService`&quot;">​</a></h3><p>This service handles the aggregation and preprocessing of external data.</p><ul><li><strong>Responsibilities:</strong><ul><li>Polling high-signal tech RSS feeds (e.g., TechCrunch, Hacker News, The Verge).</li><li>Deduplicating incoming news items.</li><li>Structuring raw feed data into a format suitable for the AI ingestion pipeline.</li></ul></li></ul><h3 id="geminiservice-llamaservice" tabindex="-1"><code>GeminiService</code> / <code>LlamaService</code> <a class="header-anchor" href="#geminiservice-llamaservice" aria-label="Permalink to &quot;`GeminiService` / `LlamaService`&quot;">​</a></h3><p>This service is the primary orchestrator for all AI interactions.</p><ul><li><strong>Responsibilities:</strong><ul><li>Generating editorial ideas from aggregated headlines.</li><li>Drafting full articles using &quot;Blueprint Prompting&quot;.</li><li>Extracting metadata (SEO tags, summaries).</li><li>Translating content on-demand.</li></ul></li><li><strong>Integration:</strong> Communicates with either the cloud-based Google Gemini 2.0 API or a local MLX-LM server running Qwen2.5-Coder.</li></ul><h2 id="best-practices-for-services" tabindex="-1">Best Practices for Services <a class="header-anchor" href="#best-practices-for-services" aria-label="Permalink to &quot;Best Practices for Services&quot;">​</a></h2><ul><li><strong>Single Responsibility:</strong> Each method inside a service should do exactly one thing. If a method grows beyond 40 lines, it should be refactored into smaller private helper methods.</li><li><strong>Error Handling:</strong> External API calls (like fetching RSS feeds or calling Gemini) must be wrapped in <code>try/catch</code> blocks. Errors must be logged with context using <code>Log::error()</code>.</li><li><strong>Rate Limiting:</strong> Ensure that calls to external APIs respect rate limits. For example, the Gemini integration includes a mandatory 10-second delay between consecutive calls to avoid 429 errors.</li></ul>',11)])])}const u=i(s,[["render",o]]);export{m as __pageData,u as default};
